with.sysid:
{%- assign sysid_group = event.alerts[0].kibana.alert.grouping.sysid -%}
{%- assign sysid_ctx = event.alerts[0].kibana.alert.context.sysid -%}
{%- assign sysid_params = event.alerts[0].kibana.alert.rule.parameters.sysid -%}
{%- if sysid_group and sysid_group != "" -%}
  {{ sysid_group }}
{%- elsif sysid_ctx and sysid_ctx != "" -%}
  {{ sysid_ctx }}
{%- elsif sysid_params and sysid_params != "" -%}
  {{ sysid_params }}
{%- endif -%}

with.systype:
{%- assign rh = steps.fetch_repair_history.output.hits.hits[0]._source.systype -%}
{%- if rh and rh != "" -%}
  {{ rh }}
{%- endif -%}

with.message:
